-- Owner-only rollback initial admission. Synthetic Auth/session facts are not provider proof.
begin;
create extension if not exists pgtap with schema extensions;
grant usage on schema extensions to cuevo_api,cuevo_worker;
set local search_path=extensions,pg_catalog;
select no_plan();
select internal.configure_worker_dispatch(false,null,null,false);
select set_config('app.runtime_env','local',true);
select ok(to_regclass('internal.initial_school_admissions')is not null,'initial pre-school approval has one private immutable source');
select ok((select relrowsecurity and relforcerowsecurity from pg_class where oid='internal.initial_school_admissions'::regclass),'initial approval forces enabled RLS');
select ok(not exists(select 1 from pg_roles role where role.rolname in('anon','authenticated','service_role','cuevo_api','cuevo_worker')and(has_table_privilege(role.oid,'internal.initial_school_admissions','SELECT,INSERT,UPDATE,DELETE,TRUNCATE')or has_any_column_privilege(role.oid,'internal.initial_school_admissions','SELECT,INSERT,UPDATE,REFERENCES'))),'initial pre-school source has no raw application or Data API grants');
select ok(not exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace cross join pg_roles role where n.nspname='internal'and p.proname in('admit_initial_school','initial_school_payload','require_initial_school_operator','process_before_initial_school_admission')and role.rolname in('anon','authenticated','service_role','cuevo_api','cuevo_worker')and has_function_privilege(role.oid,p.oid,'EXECUTE')),'initial owner command and helpers have no runtime grants');
select ok(not exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace cross join lateral aclexplode(coalesce(p.proacl,acldefault('f',p.proowner)))permission where n.nspname='internal'and p.proname in('admit_initial_school','initial_school_payload','require_initial_school_operator','process_before_initial_school_admission')and permission.grantee=0 and permission.privilege_type='EXECUTE'),'PUBLIC cannot invoke initial owner admission');
select ok((select prosecdef and 'search_path=""'=any(proconfig)from pg_proc where oid='internal.admit_initial_school(jsonb,text,text,text)'::regprocedure),'initial command is private empty-search-path definer');

create temporary table initial_test(kind text primary key,payload jsonb,receipt jsonb);
create temporary table initial_before(kind text primary key,snapshot jsonb);
grant select,insert,update on initial_test,initial_before to cuevo_api,cuevo_worker;
insert into auth.sessions(id,user_id,created_at,updated_at,not_after)values('20000000-0000-4000-8000-000000000201','20000000-0000-4000-8000-000000000001',clock_timestamp(),clock_timestamp(),clock_timestamp()+interval'1 day');
insert into auth.users(id,email,is_anonymous,email_confirmed_at,aud,role,created_at,updated_at)values('20000000-0000-4000-8000-000000000202','first-admin@initial.example.test',false,clock_timestamp(),'authenticated','authenticated',clock_timestamp(),clock_timestamp());
insert into auth.sessions(id,user_id,created_at,updated_at,not_after)values('20000000-0000-4000-8000-000000000203','20000000-0000-4000-8000-000000000202',clock_timestamp(),clock_timestamp(),clock_timestamp()+interval'1 day');
insert into initial_test(kind,payload)values('primary','{"schoolId":"20000000-0000-4000-8000-000000000204","name":"New standalone synthetic school","countryCode":"QA","languages":["en","ar"],"adminId":"20000000-0000-4000-8000-000000000202","adminEmail":"first-admin@initial.example.test","adminDisplayName":"First reviewed administrator","adminSessionId":"20000000-0000-4000-8000-000000000203","operatorSessionId":"20000000-0000-4000-8000-000000000201","controlRevision":1,"entitlements":["school.context","school.operations","learning","assessment","curriculum"],"reason":"Explicit rollback-only first-school approval","confirmApproval":true}');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000001',true);
select set_config('app.school_id','',true);
select throws_ok($$select internal.admit_initial_school(payload,'initial-admission-0001',repeat('a',64),'initial-proof')from pg_temp.initial_test where kind='primary'$$,'42501',null,'default-disabled operator control denies first school');
select internal.configure_local_school_account_runtime(true,(select oid from pg_catalog.pg_database where datname=current_database()),'LOCAL_CUEVO','20000000-0000-4000-8000-000000000001','Explicit initial test operator',(select revision from internal.school_account_runtime_control where singleton),true);
update initial_test set payload=jsonb_set(payload,'{controlRevision}',to_jsonb((select revision from internal.school_account_runtime_control where singleton)))where kind='primary';
set local role cuevo_api;
select throws_ok($$select internal.admit_initial_school(payload,'initial-admission-0001',repeat('a',64),'initial-proof')from pg_temp.initial_test where kind='primary'$$,'42501',null,'ordinary API cannot create first tenant');
reset role;
set local role cuevo_worker;
select throws_ok($$select internal.admit_initial_school(payload,'initial-admission-0001',repeat('a',64),'initial-proof')from pg_temp.initial_test where kind='primary'$$,'42501',null,'worker cannot create first tenant');
reset role;
select throws_ok($$select internal.admit_initial_school(null,'initial-admission-0001',repeat('a',64),'initial-proof')$$,'22023',null,'null source cannot invent an initial school');
select throws_ok($$select internal.admit_initial_school(payload||'{"serviceKey":"private"}','initial-admission-0001',repeat('a',64),'initial-proof')from pg_temp.initial_test where kind='primary'$$,'22023',null,'unknown privileged/credential fields are refused');
select throws_ok($$select internal.admit_initial_school(payload||'{"confirmApproval":false}','initial-admission-0001',repeat('a',64),'initial-proof')from pg_temp.initial_test where kind='primary'$$,'22023',null,'initial school requires explicit human confirmation');
select throws_ok($$select internal.admit_initial_school(payload||'{"entitlements":["school.context","school.operations","all"]}','initial-admission-0001',repeat('a',64),'initial-proof')from pg_temp.initial_test where kind='primary'$$,'22023',null,'unknown capability cannot issue unrestricted module access');
select throws_ok($$select internal.admit_initial_school(payload||'{"entitlements":["school.context","learning"]}','initial-admission-0001',repeat('a',64),'initial-proof')from pg_temp.initial_test where kind='primary'$$,'22023',null,'standalone first admin requires explicit school operations');
select throws_ok($$select internal.admit_initial_school(payload||'{"languages":["en","en"]}','initial-admission-0001',repeat('a',64),'initial-proof')from pg_temp.initial_test where kind='primary'$$,'22023',null,'languages cannot duplicate or add an unsupported axis');
select throws_ok($$select internal.admit_initial_school(payload||'{"adminEmail":"foreign@example.test"}','initial-admission-0001',repeat('a',64),'initial-proof')from pg_temp.initial_test where kind='primary'$$,'42501',null,'admin UUID and exact confirmed provider email must agree');
select throws_ok($$select internal.admit_initial_school(payload||'{"adminSessionId":"20000000-0000-4000-8000-000000000201"}','initial-admission-0001',repeat('a',64),'initial-proof')from pg_temp.initial_test where kind='primary'$$,'42501',null,'operator session cannot serve as recipient consent');
select throws_ok($$select internal.admit_initial_school(payload||'{"operatorSessionId":"20000000-0000-4000-8000-000000000203"}','initial-admission-0001',repeat('a',64),'initial-proof')from pg_temp.initial_test where kind='primary'$$,'42501',null,'recipient session cannot authorize the operator');
select throws_ok($$select internal.admit_initial_school(payload||'{"controlRevision":999}','initial-admission-0001',repeat('a',64),'initial-proof')from pg_temp.initial_test where kind='primary'$$,'42501',null,'current immutable operator control revision is required');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000004',true);
select throws_ok($$select internal.admit_initial_school(payload,'initial-admission-0001',repeat('a',64),'initial-proof')from pg_temp.initial_test where kind='primary'$$,'42501',null,'arbitrary owner actor cannot borrow an operator session');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000001',true);
select throws_ok($$select internal.admit_initial_school(payload||'{"adminId":"20000000-0000-4000-8000-000000000001","adminEmail":"synthetic.admin1@example.test","adminSessionId":"20000000-0000-4000-8000-000000000201"}','initial-admission-0001',repeat('a',64),'initial-proof')from pg_temp.initial_test where kind='primary'$$,'42501',null,'operator cannot stand in for a separate consenting initial administrator');
update auth.users set is_anonymous=true where id='20000000-0000-4000-8000-000000000202';
select throws_ok($$select internal.admit_initial_school(payload,'initial-admission-0001',repeat('a',64),'initial-proof')from pg_temp.initial_test where kind='primary'$$,'42501',null,'anonymous provider account cannot be first administrator');
update auth.users set is_anonymous=false,email_confirmed_at=null where id='20000000-0000-4000-8000-000000000202';
select throws_ok($$select internal.admit_initial_school(payload,'initial-admission-0001',repeat('a',64),'initial-proof')from pg_temp.initial_test where kind='primary'$$,'42501',null,'unconfirmed provider email cannot admit school');
update auth.users set email_confirmed_at=clock_timestamp(),banned_until=clock_timestamp()+interval'1 day'where id='20000000-0000-4000-8000-000000000202';
select throws_ok($$select internal.admit_initial_school(payload,'initial-admission-0001',repeat('a',64),'initial-proof')from pg_temp.initial_test where kind='primary'$$,'42501',null,'currently banned administrator cannot admit school');
update auth.users set banned_until=null where id='20000000-0000-4000-8000-000000000202';
update auth.sessions set not_after=clock_timestamp()-interval'1 second'where id='20000000-0000-4000-8000-000000000203';
select throws_ok($$select internal.admit_initial_school(payload,'initial-admission-0001',repeat('a',64),'initial-proof')from pg_temp.initial_test where kind='primary'$$,'42501',null,'expired recipient session cannot consent');
update auth.sessions set not_after=clock_timestamp()+interval'1 day'where id='20000000-0000-4000-8000-000000000203';
select is((select count(*)from app.schools where id='20000000-0000-4000-8000-000000000204'),0::bigint,'all denied initial admissions leave school absent');
select is((select count(*)from app.memberships where actor_id='20000000-0000-4000-8000-000000000202'),0::bigint,'denied initial admissions never fabricate pending admin');
update initial_test set receipt=internal.admit_initial_school(payload,'initial-admission-0001',repeat('a',64),'initial-proof')where kind='primary';
select is((select receipt->>'status'from initial_test where kind='primary'),'ADMITTED','exact current operator and consenting first admin admit one school');
select is((select receipt->>'id'from initial_test where kind='primary'),'20000000-0000-4000-8000-000000000204','response retains approved school identity');
select is((select receipt->>'administratorId'from initial_test where kind='primary'),'20000000-0000-4000-8000-000000000202','response retains exact verified first administrator');
select is(internal.admit_initial_school(payload,'initial-admission-0001',repeat('a',64),'initial-replay'),receipt,'same original key reconciles current source without another tenant')from initial_test where kind='primary';
select is((select count(*)from internal.initial_school_admissions where school_id='20000000-0000-4000-8000-000000000204'),1::bigint,'one immutable initial approval persists');
select is((select count(*)from app.memberships where school_id='20000000-0000-4000-8000-000000000204'),1::bigint,'only one actual active first admin is inserted');
select is((select role from app.memberships where school_id='20000000-0000-4000-8000-000000000204'),'admin','approved first actor receives admin role');
select ok((select synthetic from app.people where school_id='20000000-0000-4000-8000-000000000204'),'local operator school remains entirely synthetic');
select is((select count(*)from app.entitlements where school_id='20000000-0000-4000-8000-000000000204'and enabled),5::bigint,'only five explicitly approved existing capabilities are inserted');
select is((select count(*)from app.courses where school_id='20000000-0000-4000-8000-000000000204'),0::bigint,'initial admission invents no curriculum/course source');
select is((select count(*)from internal.audit_events where school_id='20000000-0000-4000-8000-000000000204'and action='school.initial_admitted'and actor_id='20000000-0000-4000-8000-000000000202'),1::bigint,'canonical audit identifies actual consenting first admin');
select is((select operator_id from internal.initial_school_admissions where school_id='20000000-0000-4000-8000-000000000204'),'20000000-0000-4000-8000-000000000001'::uuid,'private source separately retains operator provenance');
select is((select actor_id from internal.school_access_revisions where school_id='20000000-0000-4000-8000-000000000204'and resource='memberships'and revision=1),'20000000-0000-4000-8000-000000000001'::uuid,'membership history records true unchanged operator GUC');
select is("authorization".actor_id(),'20000000-0000-4000-8000-000000000001'::uuid,'owner command never switches actor to impersonate admin');
select is((select count(*)from internal.idempotency_keys where school_id='20000000-0000-4000-8000-000000000204'and actor_id='20000000-0000-4000-8000-000000000202'and command='school.initial.admit'),1::bigint,'canonical initial receipt has one actual first-admin actor key');
select throws_ok($$select internal.admit_initial_school(payload||'{"name":"Changed school"}','initial-admission-0001',repeat('b',64),'initial-changed')from pg_temp.initial_test where kind='primary'$$,'22023',null,'original key cannot change reviewed intent');
select throws_ok($$select internal.admit_initial_school(payload,'initial-admission-0002',repeat('b',64),'initial-duplicate')from pg_temp.initial_test where kind='primary'$$,'22023',null,'new key cannot create existing tenant or reattach admin');
update app.entitlements set enabled=false where school_id='20000000-0000-4000-8000-000000000204'and code='learning';
select throws_ok($$select internal.admit_initial_school(payload,'initial-admission-0001',repeat('a',64),'initial-learning-replay')from pg_temp.initial_test where kind='primary'$$,'42501',null,'original initial receipt rechecks each approved capability while school access remains current');
update app.entitlements set enabled=true where school_id='20000000-0000-4000-8000-000000000204'and code='learning';
update app.people set synthetic=false where school_id='20000000-0000-4000-8000-000000000204'and actor_id='20000000-0000-4000-8000-000000000202';
select throws_ok($$select internal.admit_initial_school(payload,'initial-admission-0001',repeat('a',64),'initial-mixed-replay')from pg_temp.initial_test where kind='primary'$$,'42501',null,'mixed real/synthetic population denies original admission replay');
update app.people set synthetic=true where school_id='20000000-0000-4000-8000-000000000204'and actor_id='20000000-0000-4000-8000-000000000202';
select throws_ok($$update internal.initial_school_admissions set fingerprint=repeat('b',64)where school_id='20000000-0000-4000-8000-000000000204'$$,'55000',null,'initial approval cannot be rewritten');
select throws_ok($$delete from internal.initial_school_admissions where school_id='20000000-0000-4000-8000-000000000204'$$,'55000',null,'initial receipt cannot be deleted');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000202',true);
select set_config('app.school_id','20000000-0000-4000-8000-000000000204',true);
set local role cuevo_api;
select ok("authorization".can_access_school('20000000-0000-4000-8000-000000000204'),'new admin uses ordinary current-school authority');
select lives_ok($$select internal.school_context()$$,'new administrator satisfies ordinary school context surface');
reset role;
select set_config('app.actor_id','20000000-0000-4000-8000-000000000001',true);
select set_config('app.school_id','',true);
update app.entitlements set enabled=false where school_id='20000000-0000-4000-8000-000000000204'and code='school.operations';
select throws_ok($$select internal.admit_initial_school(payload,'initial-admission-0001',repeat('a',64),'initial-replay')from pg_temp.initial_test where kind='primary'$$,'42501',null,'original receipt cannot restore revoked entitlement');
update app.entitlements set enabled=true where school_id='20000000-0000-4000-8000-000000000204'and code='school.operations';
update app.memberships set status='revoked'where school_id='20000000-0000-4000-8000-000000000204'and actor_id='20000000-0000-4000-8000-000000000202';
select throws_ok($$select internal.admit_initial_school(payload,'initial-admission-0001',repeat('a',64),'initial-replay')from pg_temp.initial_test where kind='primary'$$,'42501',null,'original receipt cannot resurrect revoked administrator');
update app.memberships set status='active'where school_id='20000000-0000-4000-8000-000000000204'and actor_id='20000000-0000-4000-8000-000000000202';
select throws_ok($$select internal.admit_initial_school(payload,'initial-admission-0001',repeat('a',64),'initial-replay')from pg_temp.initial_test where kind='primary'$$,'42501',null,'restoring current role does not erase changed approved revision');
insert into initial_before select 'event',to_jsonb(e)from internal.outbox_events e where e.school_id='20000000-0000-4000-8000-000000000204'and e.type='school.initial_admitted';
update internal.outbox_events set state='PROCESSING',attempt_count=1,lease_token='20000000-0000-4000-8000-000000000205',lease_until=clock_timestamp()+interval'1 minute'where school_id='20000000-0000-4000-8000-000000000204'and type='school.initial_admitted';
set local role cuevo_worker;
select is(internal.process_learner_event((select(snapshot->>'id')::uuid from initial_before where kind='event'),'20000000-0000-4000-8000-000000000205'),' {"status":"ACKNOWLEDGED"}'::jsonb,'worker acknowledges immutable admitted source without creating access again');
reset role;
select is((select state from internal.outbox_events where school_id='20000000-0000-4000-8000-000000000204'and type='school.initial_admitted'),'COMPLETED','initial event uses existing worker ledger');
select internal.configure_local_school_account_runtime(false,(select oid from pg_catalog.pg_database where datname=current_database()),'LOCAL_CUEVO','20000000-0000-4000-8000-000000000001','Pause initial owner test',(select revision from internal.school_account_runtime_control where singleton),true);
select throws_ok($$select internal.admit_initial_school(payload,'initial-admission-0001',repeat('a',64),'initial-replay')from pg_temp.initial_test where kind='primary'$$,'42501',null,'paused control denies before old admission replay');
select*from finish();rollback;
